BEGIN;
CREATE SCHEMA pdm;
REVOKE ALL ON SCHEMA pdm FROM PUBLIC;
CREATE TABLE pdm.participants(id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);
CREATE TABLE pdm.consent_versions(version text PRIMARY KEY, document text NOT NULL, approved_at timestamptz, approval_reference text);
CREATE TABLE pdm.consents(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, version text NOT NULL REFERENCES pdm.consent_versions, granted boolean NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pdm.questions(id text NOT NULL, version text NOT NULL, domain text NOT NULL, content jsonb NOT NULL, calibration_status text NOT NULL DEFAULT 'uncalibrated', PRIMARY KEY(id,version));
CREATE TABLE pdm.rubrics(id text NOT NULL, version text NOT NULL, anchors jsonb NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE pdm.graph_nodes(id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('question','concept','position','argument','objection')), content jsonb NOT NULL);
CREATE TABLE pdm.graph_edges(id text PRIMARY KEY, source text NOT NULL REFERENCES pdm.graph_nodes, target text NOT NULL REFERENCES pdm.graph_nodes, relation text NOT NULL CHECK(relation IN ('prerequisite','supports','objects-to','responds-to','implies','distinguishes','historically-associated-with')), contested boolean NOT NULL, rationale text NOT NULL);
CREATE TABLE pdm.sessions(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, mode text NOT NULL CHECK(mode IN ('assessment','explore')), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(id,participant_id));
CREATE TABLE pdm.responses(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, session_id uuid NOT NULL, question_id text NOT NULL, question_version text NOT NULL, original_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES pdm.sessions(id,participant_id) ON DELETE CASCADE, FOREIGN KEY(question_id,question_version) REFERENCES pdm.questions(id,version), UNIQUE(id,participant_id));
CREATE TABLE pdm.revisions(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, response_id uuid NOT NULL, revision_no integer NOT NULL CHECK(revision_no>0), text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(response_id,participant_id) REFERENCES pdm.responses(id,participant_id) ON DELETE CASCADE, UNIQUE(response_id,revision_no));
CREATE TABLE pdm.model_prompts(id text PRIMARY KEY, provider text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, prompt_hash text NOT NULL);
CREATE TABLE pdm.ratings(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, response_id uuid NOT NULL, dimension text NOT NULL CHECK(dimension IN ('justification','assumptions','counterargument','consistency','precision','integration')), score smallint CHECK(score BETWEEN 0 AND 4), applicable_max smallint NOT NULL CHECK(applicable_max=4), missing_reason text, evidence text, rationale text NOT NULL, rater_type text NOT NULL CHECK(rater_type IN ('self','human','ai')), rater_id text NOT NULL, rubric_id text NOT NULL, rubric_version text NOT NULL, model_prompt_id text REFERENCES pdm.model_prompts, abstained boolean NOT NULL DEFAULT false, rated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(response_id,participant_id) REFERENCES pdm.responses(id,participant_id) ON DELETE CASCADE, FOREIGN KEY(rubric_id,rubric_version) REFERENCES pdm.rubrics(id,version), CHECK(score IS NULL OR coalesce(length(evidence),0)>0), CHECK(score IS NOT NULL OR coalesce(length(missing_reason),0)>0), CHECK(rater_type<>'ai' OR model_prompt_id IS NOT NULL));
CREATE TABLE pdm.analysis_runs(id uuid PRIMARY KEY, code_commit text NOT NULL, specification text NOT NULL, input_manifest_hash text NOT NULL, seed bigint, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pdm.estimates(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, run_id uuid NOT NULL REFERENCES pdm.analysis_runs, dimension text NOT NULL, estimate double precision NOT NULL, standard_error double precision CHECK(standard_error>=0), method text NOT NULL, input_response_ids uuid[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pdm.calibrations(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES pdm.analysis_runs, question_id text NOT NULL, question_version text NOT NULL, model text NOT NULL, parameters jsonb NOT NULL, sample_description text NOT NULL, diagnostics jsonb NOT NULL, FOREIGN KEY(question_id,question_version) REFERENCES pdm.questions(id,version));
CREATE TABLE pdm.achievements(participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, achievement text NOT NULL, awarded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(participant_id,achievement));
CREATE TABLE pdm.assignments(participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, study_version text NOT NULL, condition text NOT NULL, randomization_seed bigint NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(participant_id,study_version));
CREATE TABLE pdm.events(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, session_id uuid, category text NOT NULL, model_prompt_id text REFERENCES pdm.model_prompts, latency_ms integer CHECK(latency_ms>=0), input_tokens integer CHECK(input_tokens>=0), output_tokens integer CHECK(output_tokens>=0), cost_usd numeric(12,6) CHECK(cost_usd>=0), details jsonb NOT NULL DEFAULT '{}', recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES pdm.sessions(id,participant_id) ON DELETE CASCADE);
CREATE TABLE pdm.export_requests(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, requested_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL CHECK(status IN ('pending','completed','failed')), expires_at timestamptz);
CREATE TABLE pdm.deletion_requests(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES pdm.participants ON DELETE CASCADE, requested_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL CHECK(status IN ('pending','completed','failed')));
-- Audit records intentionally contain only action/opaque request IDs, no answer text or participant identifiers.
CREATE TABLE pdm.audit_log(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, action text NOT NULL, request_id uuid NOT NULL, actor_role text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION pdm.current_participant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('pdm.participant_id',true),'')::uuid $$;
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['participants','consents','sessions','responses','revisions','ratings','estimates','achievements','assignments','events','export_requests','deletion_requests'] LOOP
EXECUTE format('ALTER TABLE pdm.%I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('ALTER TABLE pdm.%I FORCE ROW LEVEL SECURITY',t);
-- Read-only participant policy. No public writes, enrollment or consent grants.
EXECUTE format('CREATE POLICY own_read ON pdm.%I FOR SELECT USING (%I = pdm.current_participant())',t,CASE WHEN t='participants' THEN 'id' ELSE 'participant_id' END);
END LOOP; END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA pdm FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pdm FROM PUBLIC;
COMMIT;
